CREATE FUNCTION public.coach_phase_connected(c uuid,p uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT c IS NOT NULL AND c<>p AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=c AND role='coach' AND status='active') AND NOT EXISTS(SELECT 1 FROM public.user_blocks WHERE (blocker_id=c AND blocked_id=p) OR (blocker_id=p AND blocked_id=c)) AND (EXISTS(SELECT 1 FROM public.connection_requests WHERE kind='coach_player' AND status='accepted' AND ((from_user=c AND to_user=p) OR (from_user=p AND to_user=c))) OR EXISTS(SELECT 1 FROM public.scout_follows WHERE scout_id=c AND player_id=p AND status='accepted' AND relationship_type='linked') OR EXISTS(SELECT 1 FROM public.org_athlete_assignments a JOIN public.organization_members m ON m.organization_id=a.organization_id AND m.user_id=p AND m.status='active' JOIN public.organization_members cm ON cm.organization_id=a.organization_id AND cm.user_id=c AND cm.status='active' WHERE a.coach_user_id=c AND a.athlete_user_id=p AND a.revoked_at IS NULL)); $$;
REVOKE ALL ON FUNCTION public.coach_phase_connected(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.coach_phase_connected(uuid,uuid) TO authenticated,service_role;
CREATE TABLE public.coach_phase_tunings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),coach_id uuid NOT NULL,athlete_id uuid,phase text NOT NULL,settings jsonb NOT NULL,before_values jsonb NOT NULL,targets uuid[] NOT NULL DEFAULT '{}',prepared_at timestamptz NOT NULL DEFAULT now(),confirmed_at timestamptz,undone_at timestamptz,changed_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.coach_phase_tunings TO authenticated;
GRANT ALL ON public.coach_phase_tunings TO service_role;
ALTER TABLE public.coach_phase_tunings ENABLE ROW LEVEL SECURITY;
CREATE POLICY phase_connected_read ON public.coach_phase_tunings FOR SELECT TO authenticated USING(coach_id=auth.uid() OR (athlete_id IS NOT NULL AND public.coach_phase_connected(auth.uid(),athlete_id)));
CREATE INDEX coach_phase_lookup ON public.coach_phase_tunings(phase,athlete_id,confirmed_at DESC) WHERE confirmed_at IS NOT NULL;
CREATE TABLE public.coach_phase_readbacks(user_id uuid PRIMARY KEY,acknowledged_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.coach_phase_readbacks TO authenticated;
GRANT ALL ON public.coach_phase_readbacks TO service_role;
ALTER TABLE public.coach_phase_readbacks ENABLE ROW LEVEL SECURITY;
CREATE POLICY phase_self_read ON public.coach_phase_readbacks FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.coach_phase_effective(p uuid,ph text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE base jsonb; r public.coach_phase_tunings; nm text; BEGIN IF auth.role()<>'service_role' AND auth.uid() IS DISTINCT FROM p AND NOT public.coach_phase_connected(auth.uid(),p) THEN RAISE EXCEPTION 'Active coach-player connection required' USING ERRCODE='42501'; END IF; SELECT to_jsonb(b) INTO base FROM public.wk_periodization_blocks b WHERE phase=ph; SELECT * INTO r FROM public.coach_phase_tunings t WHERE t.phase=ph AND t.confirmed_at IS NOT NULL AND t.undone_at IS NULL AND (t.athlete_id=p OR t.athlete_id IS NULL) AND public.coach_phase_connected(t.coach_id,p) ORDER BY (t.athlete_id IS NOT NULL) DESC,t.confirmed_at DESC,t.id DESC LIMIT 1; IF r.id IS NULL THEN RETURN jsonb_build_object('settings',base,'source','owner','revision','owner'); END IF; SELECT concat_ws(' ',first_name,last_name) INTO nm FROM public.profiles WHERE id=r.coach_id; RETURN jsonb_build_object('settings',coalesce(base,'{}'::jsonb)||r.settings,'source',CASE WHEN r.athlete_id IS NULL THEN 'roster' ELSE 'player' END,'coach_id',r.coach_id,'coach_name',coalesce(nullif(nm,''),'Coach'),'changed_at',r.confirmed_at,'revision',r.id); END $$;
REVOKE ALL ON FUNCTION public.coach_phase_effective(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.coach_phase_effective(uuid,text) TO authenticated,service_role;
CREATE FUNCTION public.coach_phase_prepare(p uuid,ph text,v jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid:=auth.uid(); ids uuid[]; pid uuid; old jsonb:='{}'; rec public.coach_phase_tunings; k text; val jsonb; BEGIN IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=c AND role='coach' AND status='active') THEN RAISE EXCEPTION 'Active coach role required' USING ERRCODE='42501'; END IF; IF NOT EXISTS(SELECT 1 FROM public.wk_periodization_blocks WHERE phase=ph) THEN RAISE EXCEPTION 'Unknown phase'; END IF; IF jsonb_typeof(v)<>'object' OR v='{}'::jsonb THEN RAISE EXCEPTION 'Choose a tuning change'; END IF; FOR k,val IN SELECT * FROM jsonb_each(v) LOOP IF k NOT IN ('compound_min_sets','compound_max_sets','compound_min_reps','compound_max_reps','speed_cadence_hours','cns_unit_cap') OR jsonb_typeof(val)<>'number' OR (val#>>'{}')::numeric<>trunc((val#>>'{}')::numeric) OR (val#>>'{}')::numeric<1 THEN RAISE EXCEPTION 'Invalid tuning field or value'; END IF; END LOOP; IF p IS NOT NULL THEN IF NOT public.coach_phase_connected(c,p) THEN RAISE EXCEPTION 'Active coach-player connection required' USING ERRCODE='42501'; END IF;ids:=ARRAY[p]; ELSE SELECT array_agg(id ORDER BY id) INTO ids FROM public.profiles WHERE public.coach_phase_connected(c,id); END IF; IF coalesce(cardinality(ids),0)=0 THEN RAISE EXCEPTION 'No connected players'; END IF; FOREACH pid IN ARRAY ids LOOP old:=old||jsonb_build_object(pid::text,public.coach_phase_effective(pid,ph)); END LOOP; INSERT INTO public.coach_phase_tunings(coach_id,athlete_id,phase,settings,before_values,targets) VALUES(c,p,ph,v,old,ids) RETURNING * INTO rec; RETURN to_jsonb(rec); END $$;
REVOKE ALL ON FUNCTION public.coach_phase_prepare(uuid,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.coach_phase_prepare(uuid,text,jsonb) TO authenticated;
CREATE FUNCTION public.coach_phase_confirm(rid uuid,first_confirm boolean,second_confirm boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.coach_phase_tunings; pid uuid; actual jsonb; merged jsonb; BEGIN IF first_confirm IS DISTINCT FROM true OR second_confirm IS DISTINCT FROM true THEN RAISE EXCEPTION 'Two confirmations required'; END IF; PERFORM pg_advisory_xact_lock(hashtext('coach-phase-tuning')); SELECT * INTO r FROM public.coach_phase_tunings WHERE id=rid AND coach_id=auth.uid() FOR UPDATE; IF r.id IS NULL OR r.confirmed_at IS NOT NULL OR r.prepared_at<now()-interval '15 minutes' THEN RAISE EXCEPTION 'Review a fresh change first'; END IF; FOREACH pid IN ARRAY r.targets LOOP IF NOT public.coach_phase_connected(auth.uid(),pid) THEN RAISE EXCEPTION 'Connection changed; review again' USING ERRCODE='42501'; END IF; actual:=public.coach_phase_effective(pid,r.phase); IF actual IS DISTINCT FROM r.before_values->pid::text THEN RAISE EXCEPTION 'Settings changed; review fresh old and new values' USING ERRCODE='40001'; END IF; merged:=(actual->'settings')||r.settings; IF (merged->>'compound_min_sets')::int>(merged->>'compound_max_sets')::int OR (merged->>'compound_min_reps')::int>(merged->>'compound_max_reps')::int THEN RAISE EXCEPTION 'Minimum must not exceed maximum'; END IF; END LOOP; UPDATE public.coach_phase_tunings SET confirmed_at=clock_timestamp(),changed_at=clock_timestamp() WHERE id=rid RETURNING * INTO r; RETURN to_jsonb(r); END $$;
REVOKE ALL ON FUNCTION public.coach_phase_confirm(uuid,boolean,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.coach_phase_confirm(uuid,boolean,boolean) TO authenticated;
CREATE FUNCTION public.coach_phase_undo(rid uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.coach_phase_tunings; pid uuid; BEGIN PERFORM pg_advisory_xact_lock(hashtext('coach-phase-tuning')); SELECT * INTO r FROM public.coach_phase_tunings WHERE id=rid AND coach_id=auth.uid() FOR UPDATE; IF r.id IS NULL OR r.confirmed_at IS NULL OR r.undone_at IS NOT NULL THEN RAISE EXCEPTION 'This change cannot be undone'; END IF; FOREACH pid IN ARRAY r.targets LOOP IF NOT public.coach_phase_connected(auth.uid(),pid) THEN RAISE EXCEPTION 'Active coach-player connection required' USING ERRCODE='42501'; END IF;END LOOP; IF EXISTS(SELECT 1 FROM public.coach_phase_tunings t WHERE t.phase=r.phase AND t.confirmed_at>r.confirmed_at AND t.undone_at IS NULL AND t.athlete_id IS NOT DISTINCT FROM r.athlete_id AND (r.athlete_id IS NOT NULL OR t.coach_id=r.coach_id)) THEN RAISE EXCEPTION 'A newer change exists; review it before Undo'; END IF; UPDATE public.coach_phase_tunings SET undone_at=clock_timestamp(),changed_at=clock_timestamp() WHERE id=rid RETURNING * INTO r; RETURN to_jsonb(r); END $$;
REVOKE ALL ON FUNCTION public.coach_phase_undo(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.coach_phase_undo(uuid) TO authenticated;
CREATE FUNCTION public.coach_phase_pending() RETURNS timestamptz LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT max(t.changed_at) FROM public.coach_phase_tunings t WHERE confirmed_at IS NOT NULL AND (athlete_id=auth.uid() OR (athlete_id IS NULL AND public.coach_phase_connected(coach_id,auth.uid()))) AND public.coach_phase_connected(coach_id,auth.uid()) AND t.changed_at>coalesce((SELECT acknowledged_at FROM public.coach_phase_readbacks WHERE user_id=auth.uid()),'-infinity'::timestamptz); $$;
CREATE FUNCTION public.coach_phase_ack(at_time timestamptz) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR at_time IS NULL OR at_time>now() THEN RAISE EXCEPTION 'Invalid acknowledgement'; END IF; INSERT INTO public.coach_phase_readbacks(user_id,acknowledged_at) VALUES(auth.uid(),at_time) ON CONFLICT(user_id) DO UPDATE SET acknowledged_at=greatest(coach_phase_readbacks.acknowledged_at,EXCLUDED.acknowledged_at); END $$;
REVOKE ALL ON FUNCTION public.coach_phase_pending() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.coach_phase_ack(timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.coach_phase_pending(),public.coach_phase_ack(timestamptz) TO authenticated;